  output logic                o_strip_valid,
  output logic [LEN_W-1:0]    o_strip_bytes,

  // Record, registered, one pulse per packet.
  output logic                o_rec_valid,
  output logic [0:0]         o_layer_valid,
  output logic [2:0]          o_err,
  output logic [LEN_W-1:0]    o_hdr_bytes,

  output logic [31:0]         o_feed_hdr_session_id,
  output logic [63:0]         o_feed_hdr_seq_num,
  output logic [15:0]         o_feed_hdr_msg_count,
