  // --------------------------------------------------------------------------
  // layer 1/1: feed_hdr -- 16 bytes of fields
  // --------------------------------------------------------------------------
  logic [LEN_W-1:0]  off_feed_hdr;
  logic [LEN_W-1:0]  len_feed_hdr;
  logic [127:0] win_feed_hdr;

  assign off_feed_hdr = LEN_W'(0);

  assign win_feed_hdr = i_win[0 +: 128];

  logic [31:0]         feed_hdr_session_id   ;  // bits 0..31, 32b uint, big-endian
  logic [63:0]         feed_hdr_seq_num      ;  // bits 32..95, 64b uint, big-endian
  logic [15:0]         feed_hdr_msg_count    ;  // bits 96..111, 16b uint, big-endian
  logic [15:0]         feed_hdr_reserved     ;  // bits 112..127, 16b uint, big-endian

  assign feed_hdr_session_id    = {win_feed_hdr[7:0], win_feed_hdr[15:8], win_feed_hdr[23:16], win_feed_hdr[31:24]};
  assign feed_hdr_seq_num       = {win_feed_hdr[39:32], win_feed_hdr[47:40], win_feed_hdr[55:48], win_feed_hdr[63:56], win_feed_hdr[71:64], win_feed_hdr[79:72], win_feed_hdr[87:80], win_feed_hdr[95:88]};
  assign feed_hdr_msg_count     = {win_feed_hdr[103:96], win_feed_hdr[111:104]};
  assign feed_hdr_reserved      = {win_feed_hdr[119:112], win_feed_hdr[127:120]};

  assign len_feed_hdr = LEN_W'(16);

  // --------------------------------------------------------------------------
  // Chain walk
  // --------------------------------------------------------------------------
  logic active_feed_hdr;
  logic trunc_fix_feed_hdr;
  logic ok_feed_hdr;
  logic settled_feed_hdr;

  assign active_feed_hdr    = 1'b1;
  assign trunc_fix_feed_hdr = i_have < (off_feed_hdr + LEN_W'(16));
  assign ok_feed_hdr        = active_feed_hdr && !trunc_fix_feed_hdr;
  assign settled_feed_hdr   = ok_feed_hdr;

